/*
 * A387601  a(n) = (1/2) * Sum_{k=0..floor(n/4)} 2^k *
 *          binomial(2*n-6*k+2,2*k+1).
 * https://oeis.org/A387601
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = 2*a(n-1) – a(n-2) + 4*a(n-4) + 4*a(n-5) – 4*a(n-8) with
 *            initial terms a(0)=1, a(1)=2, a(2)=3, a(3)=4, a(4)=9, a(5)=26,
 *            a(6)=63, a(7)=128. The sequence is generated by the recurrence,
 *            so a(n) can be obtained for any n ≥ 0. The implementation keeps
 *            a small cache for memoisation, allowing cal...
 * Range:     u8 n <= 8, u16 n <= 15, u32 n <= 30, u64 n <= 59, u128 n <= 118,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <assert.h>

static seq_t *cache         = NULL;
static size_t cache_len     = 0;   /* number of computed elements */
static size_t cache_cap     = 0;   /* capacity of the cache */

/* Ensure the cache contains indices 0 .. n (inclusive). */
static void grow_cache(idx_t n)
{
    if (cache_len > (size_t)n)          /* already available */
        return;

    /* Allocate enough storage for indices 0 .. n. */
    size_t needed = (size_t)n + 1;
    if (needed > cache_cap) {
        size_t new_cap = (cache_cap > 0) ? cache_cap * 2 : 8;
        while (new_cap < needed)
            new_cap <<= 1;
        seq_t *new_ptr = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (!new_ptr)
            abort();                    /* out of memory */
        cache = new_ptr;
        cache_cap = new_cap;
    }

    /* First time: initialise the base values up to index 7. */
    if (cache_len == 0) {
        cache[0] = (seq_t)1;
        cache[1] = (seq_t)2;
        cache[2] = (seq_t)3;
        cache[3] = (seq_t)4;
        cache[4] = (seq_t)9;
        cache[5] = (seq_t)26;
        cache[6] = (seq_t)63;
        cache[7] = (seq_t)128;
        cache_len = 8;                  /* last base index computed */
    }

    /* Compute missing terms using the recurrence.  The recurrence
       is valid for n ≥ 8, so we start from cache_len (≥ 8). */
    for (idx_t i = (idx_t)cache_len; i <= n; ++i) {
        /* All operands are valid because i ≥ 8 and cache_len ≥ 8. */
        seq_t a1 = cache[i-1];     /* a(n-1) */
        seq_t a2 = cache[i-2];     /* a(n-2) */
        seq_t a4 = cache[i-4];     /* a(n-4) */
        seq_t a5 = cache[i-5];     /* a(n-5) */
        seq_t a8 = cache[i-8];     /* a(n-8) */

        seq_t val = 2 * a1;        /* 2*a(n-1) */
        val -= a2;                 /* -a(n-2)   */
        val += 4 * a4;             /* +4*a(n-4) */
        val += 4 * a5;             /* +4*a(n-5) */
        val -= 4 * a8;             /* -4*a(n-8) */
        cache[i] = val;
    }

    /* Update the length of the computed prefix. */
    if ((size_t)(n + 1) > cache_len)
        cache_len = (size_t)(n + 1);
}

seq_t a(idx_t n)
{
    grow_cache(n);
    return cache[n];
}
